SELECT r.patch_major,r.win,json_extract(r.raw_json,'$.build_id'),
 (SELECT json_group_array(json_object('id',json_extract(d.value,'$.id'),'current_upgrade_level',json_extract(d.value,'$.current_upgrade_level'),'upgrade_level',json_extract(d.value,'$.upgrade_level'),'times_upgraded',json_extract(d.value,'$.times_upgraded'),'upgraded',json_extract(d.value,'$.upgraded'))) FROM json_each(r.raw_json,'$.players[0].deck') d),
 (SELECT json_group_array(json_object('act_index',a.key,'room_type',json_extract(room.value,'$.room_type'),'encounter_id',json_extract(room.value,'$.model_id'))) FROM json_each(r.raw_json,'$.map_point_history') a JOIN json_each(a.value) p JOIN json_each(p.value,'$.rooms') room)
 FROM runs r WHERE r.character='SILENT' AND r.ascension=10 AND r.n_players=1 AND r.is_valid=1 AND r.was_abandoned=0 AND r.has_modifiers=0 AND r.patch_major IN ('v0.107','v0.108','v0.109','v0.110','v0.111');
